// Usage: node generate.mjs [--check]. Writes src/theme/generated/*. --check fails if committed files are stale.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { buildModel, THEME_DIR, flatSemantic, toHex } from "./lib/model.mjs";

const OUT = path.join(THEME_DIR, "generated");
const HEADER =
  "GENERATED by src/theme/build/generate.mjs from src/theme/tokens/*.json. Do not edit. Run: yarn theme:build";
const css = (vars, indent = "  ") =>
  Object.entries(vars)
    .map(([k, v]) => `${indent}${k}: ${v};`)
    .join("\n");
const json = (o) => JSON.stringify(o, null, 2);

function semanticClasses(model) {
  const light = model.semantic.light;
  const make = (category, filter) =>
    Object.fromEntries(
      Object.entries(light[category])
        .filter(([name]) => filter(name))
        .map(([name, value]) => [
          name,
          `color-mix(in srgb, var(--${category}-${name}, ${value}) calc(<alpha-value> * 100%), transparent)`,
        ])
    );
  const accent = (category) => make(category, (n) => n.startsWith("accent-"));
  const ink = accent("ink");
  const surface = accent("surface");
  const outline = accent("outline");
  return {
    textColor: { ink },
    fill: { ink, surface },
    stroke: { ink },
    placeholderColor: { ink },
    backgroundColor: { surface },
    gradientColorStops: { ink, surface, outline },
    borderColor: { outline },
    ringColor: { outline },
    divideColor: { outline },
  };
}

function renderTailwindTheme(model) {
  const { ramps, delta } = model;
  const extend = {
    colors: {
      gray: ramps.gray.light,
      "dark-gray": ramps.gray.dark,
      accent: ramps.accent.light,
      "dark-accent": ramps.accent.dark,
      // Fixed brand colors that do not flip with the theme, e.g. text on a photo scrim.
      paper: model.src.palette.anchors.paper,
      charcoal: model.src.palette.anchors.charcoal,
    },
    ...semanticClasses(model),
  };
  return `// ${HEADER}
// Applied in tailwind.config.js as \`theme.extend\` and a top-level plugin, not as a second preset:
// a preset listed after frappe-ui's breaks its @apply rules, and a user plugin is emitted after preset plugins.
import plugin from "tailwindcss/plugin";

export const delta = ${json(delta)};

export const extend = ${json(extend)};

export const themePlugin = plugin(({ addBase }) => {
  addBase({ ":root": delta.light, '[data-theme="dark"]': delta.dark });
});
`;
}

function renderStandaloneCss(model) {
  return `/* ${HEADER}
   Full variable set for pages that do not load frappe-ui (login, website). */
:root {
  /* Fixed palette anchors that do not flip with the theme. */
${css(
  Object.fromEntries(
    Object.entries(model.src.palette.anchors).map(([k, v]) => [
      `--brand-${k}`,
      v,
    ])
  )
)}
}

:root,
[data-theme="light"] {
  color-scheme: light;
${css(model.full.light)}
}

[data-theme="dark"] {
  color-scheme: dark;
${css(model.full.dark)}
}
`;
}

function renderDeskCss(model) {
  const g = model.ramps.gray.light;
  const scale = Object.fromEntries(
    ["50", "100", "200", "300", "400", "500", "600", "700", "800", "900"].map(
      (s) => [`--gray-${s}`, g[s]]
    )
  );
  const ring = (mode, w) =>
    `0 0 0 ${w} ${
      model.ramps.accent[mode][model.src.semantic.focus[mode].shade]
    }`;
  return `/* ${HEADER}
   Frappe Desk keeps one gray scale for both themes and inverts usage in dark mode. */
:root,
[data-theme="light"],
html[data-theme="dark"],
[data-theme="dark"] {
${css(scale)}
}

:root,
[data-theme="light"] {
  /* Desk writes literal white for these four, so the page would stay pure white. */
  --bg-color: ${model.ramps.neutral.white};
  --fg-color: ${model.ramps.neutral.white};
  --navbar-bg: ${model.ramps.neutral.white};
  --modal-bg: ${model.ramps.neutral.white};
  --focus-default: ${ring("light", "2px")};
}

[data-theme="dark"] {
  /* Desk's own dark values, restated: the light block above would otherwise leak into dark. */
  --bg-color: var(--gray-900);
  --fg-color: var(--gray-900);
  --navbar-bg: var(--gray-900);
  --modal-bg: var(--gray-900);
  --focus-default: ${ring("dark", "3px")};
}
`;
}

// A role maps to a semantic token, or to {light, dark}; "palette/<anchor>" names a palette anchor.
function pickHex(model, map, mode) {
  const flat = flatSemantic(model.semantic, mode);
  const resolve = (token) =>
    token.startsWith("palette/")
      ? model.src.palette.anchors[token.slice("palette/".length)]
      : toHex(flat[token]);
  return Object.fromEntries(
    Object.entries(map).map(([role, token]) => [
      role,
      resolve(typeof token === "object" ? token[mode] : token),
    ])
  );
}

function renderTokensTs(model) {
  const mode = (m) =>
    Object.fromEntries(
      Object.entries(flatSemantic(model.semantic, m))
        .map(([k, v]) => [k, toHex(v)])
        .filter(([, v]) => v)
    );
  const series = (m) =>
    model.src.semantic.chart.series[m].map((ref) => {
      const [fam, shade] = ref.split("/");
      return model.ramps[fam][m][shade];
    });
  const out = {
    palette: model.src.palette.anchors,
    light: mode("light"),
    dark: mode("dark"),
    chart: {
      series: { light: series("light"), dark: series("dark") },
      ui: {
        light: pickHex(model, model.src.semantic.chart.ui, "light"),
        dark: pickHex(model, model.src.semantic.chart.ui, "dark"),
      },
    },
    email: {
      light: pickHex(model, model.src.semantic.email, "light"),
      dark: pickHex(model, model.src.semantic.email, "dark"),
    },
  };
  return `// ${HEADER}
export type ThemeMode = "light" | "dark";

export const tokens = ${json(out)} as const;

export type SemanticToken = keyof typeof tokens.light;
`;
}

function renderEmailJson(model) {
  return (
    json({
      light: pickHex(model, model.src.semantic.email, "light"),
      dark: pickHex(model, model.src.semantic.email, "dark"),
    }) + "\n"
  );
}

// Server-side code (emails, report and chart defaults) cannot read CSS variables or tokens.ts.
// This emits the same values as a Python module, formatted the way black would.
const NL = String.fromCharCode(10);
function pyLiteral(value, depth = 0) {
  const pad = "    ".repeat(depth + 1);
  const end = "    ".repeat(depth);
  const lines = (items) => items.join(NL);
  if (Array.isArray(value))
    return `[${NL}${lines(value.map((v) => `${pad}${pyLiteral(v, depth + 1)},`))}${NL}${end}]`;
  if (value && typeof value === "object")
    return `{${NL}${lines(
      Object.entries(value).map(
        ([k, v]) => `${pad}${JSON.stringify(k)}: ${pyLiteral(v, depth + 1)},`
      )
    )}${NL}${end}}`;
  if (value === null) return "None";
  if (typeof value === "boolean") return value ? "True" : "False";
  return JSON.stringify(value);
}

function renderThemePy(model) {
  const series = (m) =>
    model.src.semantic.chart.series[m].map((ref) => {
      const [fam, shade] = ref.split("/");
      return model.ramps[fam][m][shade];
    });
  const both = (map) => ({
    light: pickHex(model, map, "light"),
    dark: pickHex(model, map, "dark"),
  });
  return `# ${HEADER}
"""Palette values for server-side code (emails, reports, chart defaults)."""

EMAIL = ${pyLiteral(both(model.src.semantic.email))}

CHART_SERIES = ${pyLiteral({ light: series("light"), dark: series("dark") })}

CHART_UI = ${pyLiteral(both(model.src.semantic.chart.ui))}
`;
}

export async function render() {
  const model = await buildModel();
  return {
    model,
    files: {
      "tailwind-theme.mjs": renderTailwindTheme(model),
      "nxerp-theme.css": renderStandaloneCss(model),
      "frappe-desk.css": renderDeskCss(model),
      "tokens.ts": renderTokensTs(model),
      "email.json": renderEmailJson(model),
      "theme_tokens.py": renderThemePy(model),
    },
  };
}

if (
  import.meta.url === `file://${process.argv[1].replace(/\\/g, "/")}` ||
  process.argv[1]?.endsWith("generate.mjs")
) {
  const check = process.argv.includes("--check");
  const { files, model } = await render();
  fs.mkdirSync(OUT, { recursive: true });
  let stale = 0;
  for (const [name, content] of Object.entries(files)) {
    const file = path.join(OUT, name);
    const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null;
    if (check) {
      if (current !== content) {
        stale++;
        console.error(`stale: generated/${name}`);
      }
    } else if (current !== content) {
      fs.writeFileSync(file, content);
      console.log(`wrote generated/${name}`);
    }
  }
  if (check) {
    if (stale) {
      console.error(
        `${stale} generated file(s) out of date. Run: yarn theme:build`
      );
      process.exit(1);
    }
    console.log("generated files are up to date");
  } else {
    console.log(
      `frappe-ui ${model.fui.version}: ${
        Object.keys(model.delta.light).length
      } light and ${
        Object.keys(model.delta.dark).length
      } dark variables differ from stock.`
    );
  }
}
